function lazy(fn) {
  let p;
  return () => p ??= fn();
}
var countOf = count;
var labels = (rows3) => rows3.map(rowLabel);
var loadHandlers2 = (org) => lazy(async () => {
  const rows3 = await query(`SELECT DeveloperName, MasterLabel, IsActive FROM LifeScienceTriggerHandler`, org, true);
  return new Map(
    rows3.map((r) => [
      String(r.DeveloperName),
      { developerName: String(r.DeveloperName), label: String(r.MasterLabel || r.DeveloperName), active: !!r.IsActive }
    ])
  );
});
function handlersCheck(meta, handlers, names2) {
  return runCheck(meta, async () => {
    const all = await handlers();
    const present2 = names2.map((n) => all.get(n)).filter((h) => !!h);
    if (present2.length === 0) return { pass: true, skip: true, detail: "None of these trigger handlers exist in this org." };
    const off = present2.filter((h) => !h.active);
    if (off.length === 0) return { pass: true, detail: `${plural(present2.length, "handler")} on.` };
    return {
      pass: false,
      detail: `${off.length} of ${present2.length} switched off: ${off.map((h) => h.developerName).join(", ")}.`,
      examples: off.map((h) => h.developerName),
      fixes: off.map(
        (h) => ({
          kind: "setActive",
          label: `Switch on ${h.developerName}`,
          record: { type: "triggerHandler", developerName: h.developerName, label: h.label },
          from: false,
          to: true
        })
      )
    };
  });
}
var loadDbSchema2 = (org) => lazy(
  () => collectCategoryRecords(org, `SELECT Id, DeveloperName, Category, MasterLabel FROM LifeSciConfigCategory WHERE Category = 'DbSchema'`, { strict: true, cache: true })
);
var sobjectOf2 = (r) => String(r.fields.SObject || "").toLowerCase();
var profileNames = (r) => r.assignments.filter((a) => a.level === "Profile").map((a) => a.name);
function dbSchemaCheck(meta, schema, objects) {
  return runCheck(meta, async () => {
    const all = await schema();
    const wanted = new Set(objects.map((o) => o.toLowerCase()));
    const mine = all.filter((r) => wanted.has(sobjectOf2(r)));
    const profiles = [...new Set(mine.filter((r) => r.isActive).flatMap(profileNames))].sort();
    const missing = [];
    const off = [];
    const unassigned = [];
    const fixes = [];
    for (const object3 of objects) {
      const recs = mine.filter((r) => sobjectOf2(r) === object3.toLowerCase());
      const live = recs.filter((r) => r.isActive);
      if (live.length) {
        if (!live.some((r) => r.isOrgLevel || r.assignments.length > 0)) unassigned.push(object3);
        continue;
      }
      if (recs.length) {
        off.push(object3);
        const r = recs[0];
        if (recs.length === 1) fixes.push({
          kind: "setActive",
          label: `Switch on ${object3} sync`,
          record: { type: "config", category: "DbSchema", developerName: r.developerName, label: r.label || r.developerName },
          from: false,
          to: true
        });
      } else {
        missing.push(object3);
        if (profiles.length) fixes.push(newDbSchema(object3, all, profiles));
      }
    }
    const problems = [
      missing.length ? `not synced: ${missing.join(", ")}` : "",
      off.length ? `switched off: ${off.join(", ")}` : "",
      unassigned.length ? `active but given to no profile: ${unassigned.join(", ")}` : ""
    ].filter(Boolean);
    if (problems.length === 0) return { pass: true, detail: `All ${objects.length} objects sync to the iPad.` };
    return { pass: false, detail: `${problems.join("; ")}.`, examples: [...missing, ...off, ...unassigned], fixes };
  });
}
async function failedJobs(org, likes, days = 14) {
  const cond = likes.map((l) => `ApexClass.Name LIKE '${l.replace(/'/g, "\\'")}'`).join(" OR ");
  return query(
    `SELECT ApexClass.Name, Status, ExtendedStatus, CreatedDate FROM AsyncApexJob WHERE JobType = 'BatchApex' AND Status IN ('Failed','Aborted') AND CreatedDate = LAST_N_DAYS:${days} AND (${cond}) ORDER BY CreatedDate DESC LIMIT 20`,
    org
  );
}

